def to_roman(n):
    if not 1 <= n <= 3999:
        raise ValueError("数字不在1到3999的范围内")
    roman_numerals = {
        1000: 'M', 900: 'CM', 500: 'D', 400: 'CD',
        100: 'C', 90: 'XC', 50: 'L', 40: 'XL',
        10: 'X', 9: 'IX', 5: 'V', 4: 'IV', 1: 'I'
    }
    roman = ''
    for value, numeral in roman_numerals.items():
        while n >= value:
            roman += numeral
            n -= value
    return roman
