def unrle(s):
    stack = []
    i = 0
    while i < len(s):
        if s[i].isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            cnt = int(s[i:j])
            i = j
        else:
            stack.append((s[i], cnt or 1))
            i += 1
    res = ''
    for ch, c in stack:
        res += ch * c
    return res
```

