def count_islands(g):
    if not g:
        return 0

    rows, cols = len(g), len(g[0])
    count = 0

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or g[r][c] != '1':
            return
        g[r][c] = '0'
        dfs(r - 1, c)
        dfs(r + 1, c)
        dfs(r, c - 1)
        dfs(r, c + 1)

    for i in range(rows):
        for j in range(cols):
            if g[i][j] == '1':
                dfs(i, j)
                count += 1

    return count
```

